You are working in /tmp/sv-4305fdba63eb45fa8351003d23baf1ca/ShipmentTracker. This is a Blazor Web App with Auto interactivity mode (Server + WebAssembly) and Individual authentication using ASP.NET Core Identity with SQLite.

The project structure:
- ShipmentTracker/ (server project) - has Program.cs, Data/ApplicationDbContext.cs, Data/ApplicationUser.cs, Components/
- ShipmentTracker.Client/ (WASM client project) - has Pages/, _Imports.razor

The ApplicationDbContext currently extends IdentityDbContext<ApplicationUser> with no extra DbSets.

## Task

Create a logistics shipment tracking feature with the following:

### 1. Shared Models (create in ShipmentTracker.Client/ since both projects reference it)

Create file `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string? CustomerEmail { get; set; }
    public string? Notes { get; set; }
}

public enum ShipmentStatus
{
    Pending,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

### 2. Entity and DbContext update

Create file `ShipmentTracker/Data/Shipment.cs`:
```csharp
using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [Required, MaxLength(50)]
    public string TrackingNumber { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }

    [MaxLength(256)]
    public string? CustomerEmail { get; set; }

    [MaxLength(500)]
    public string? Notes { get; set; }
}

public enum ShipmentStatus
{
    Pending,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

Update `ShipmentTracker/Data/ApplicationDbContext.cs` to add:
```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();
}
```

### 3. API Endpoints

Add a minimal API in Program.cs. Insert BEFORE `app.Run();` the following:

```csharp
// Shipment API endpoints
app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
    await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync())
    .RequireAuthorization();

app.MapGet("/api/shipments/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
    await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber)
        is Shipment shipment ? Results.Ok(shipment) : Results.NotFound())
    .RequireAuthorization();

app.MapPost("/api/shipments", async (Shipment shipment, ApplicationDbContext db) =>
{
    db.Shipments.Add(shipment);
    await db.SaveChangesAsync();
    return Results.Created($"/api/shipments/{shipment.TrackingNumber}", shipment);
}).RequireAuthorization();

app.MapPut("/api/shipments/{id}", async (int id, Shipment updated, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();

    shipment.Origin = updated.Origin;
    shipment.Destination = updated.Destination;
    shipment.Status = updated.Status;
    shipment.EstimatedDelivery = updated.EstimatedDelivery;
    shipment.CustomerEmail = updated.CustomerEmail;
    shipment.Notes = updated.Notes;

    await db.SaveChangesAsync();
    return Results.Ok(shipment);
}).RequireAuthorization();
```

Also add `using ShipmentTracker.Data;` at the top if not already present (it likely is via the existing using of the Data namespace).

### 4. Register HttpClient in the client project

Update `ShipmentTracker.Client/Program.cs` to register an HttpClient:
```csharp
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();
builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });

await builder.Build().RunAsync();
```

Check what the current Client/Program.cs looks like first and adjust accordingly.

### 5. Blazor Pages in ShipmentTracker.Client/Pages/

Create `ShipmentTracker.Client/Pages/Shipments.razor`:
```razor
@page "/shipments"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Shipments</PageTitle>

<h1>Shipment Management</h1>

<div class="mb-3">
    <button class="btn btn-primary" @onclick="ShowCreateForm">
        <span class="oi oi-plus"></span> New Shipment
    </button>
</div>

@if (showForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">@(editingShipment.Id == 0 ? "Create" : "Edit") Shipment</h5>
            <EditForm Model="editingShipment" OnValidSubmit="SaveShipment" FormName="shipmentForm">
                <DataAnnotationsValidator />
                <div class="row">
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Tracking Number</label>
                        <InputText class="form-control" @bind-Value="editingShipment.TrackingNumber" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Status</label>
                        <InputSelect class="form-select" @bind-Value="editingShipment.Status">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </InputSelect>
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Origin</label>
                        <InputText class="form-control" @bind-Value="editingShipment.Origin" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Destination</label>
                        <InputText class="form-control" @bind-Value="editingShipment.Destination" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Shipped Date</label>
                        <InputDate class="form-control" @bind-Value="editingShipment.ShippedDate" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Estimated Delivery</label>
                        <InputDate class="form-control" @bind-Value="editingShipment.EstimatedDelivery" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Customer Email</label>
                        <InputText class="form-control" @bind-Value="editingShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-12 mb-2">
                        <label class="form-label">Notes</label>
                        <InputTextArea class="form-control" @bind-Value="editingShipment.Notes" />
                    </div>
                </div>
                <button type="submit" class="btn btn-success me-2">Save</button>
                <button type="button" class="btn btn-secondary" @onclick="CancelEdit">Cancel</button>
            </EditForm>
        </div>
    </div>
}

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!shipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><strong>@shipment.TrackingNumber</strong></td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
                    <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    <td>
                        <button class="btn btn-sm btn-outline-primary" @onclick="() => EditShipment(shipment)">Edit</button>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private ShipmentDto editingShipment = new();
    private bool showForm;
    private string filterText = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s => string.IsNullOrEmpty(filterText)
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
            || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
    }

    private void ShowCreateForm()
    {
        editingShipment = new ShipmentDto
        {
            TrackingNumber = $"TRK-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(1000, 9999)}",
            ShippedDate = DateTime.UtcNow,
            EstimatedDelivery = DateTime.UtcNow.AddDays(5)
        };
        showForm = true;
    }

    private void EditShipment(ShipmentDto shipment)
    {
        editingShipment = new ShipmentDto
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = shipment.Status,
