using Microsoft.AspNetCore.Components.WebAssembly.Hosting;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();
builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });

await builder.Build().RunAsync();

var app = builder.Build();

// Seed the database
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();
    await SeedData.InitializeAsync(db);
}

// Configure the HTTP request pipeline.

// Shipment API endpoints
app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
    await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync())
    .RequireAuthorization();

app.MapGet("/api/shipments/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
    await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber)
        is Shipment shipment ? Results.Ok(shipment) : Results.NotFound())
    .RequireAuthorization();

app.MapPost("/api/shipments", async (Shipment shipment, ApplicationDbContext db) =>
{
    db.Shipments.Add(shipment);
    await db.SaveChangesAsync();
    return Results.Created($"/api/shipments/{shipment.TrackingNumber}", shipment);
}).RequireAuthorization();

app.MapPut("/api/shipments/{id}", async (int id, Shipment updated, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();

    shipment.Origin = updated.Origin;
    shipment.Destination = updated.Destination;
    shipment.Status = updated.Status;
    shipment.EstimatedDelivery = updated.EstimatedDelivery;
    shipment.CustomerEmail = updated.CustomerEmail;
    shipment.Notes = updated.Notes;

    await db.SaveChangesAsync();
    return Results.Ok(shipment);
}).RequireAuthorization();

app.Run();

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();
}

