```razor
@page "/track"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row justify-content-center">
    <div class="col-md-8">
        <div class="input-group mb-4">
            <input type="text" class="form-control form-control-lg" placeholder="Enter tracking number..."
                   @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary btn-lg" @onclick="SearchShipment" disabled="@isSearching">
                @if (isSearching)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>

        @if (errorMessage is not null)
        {
            <div class="alert alert-warning">@errorMessage</div>
        }

        @if (shipment is not null)
        {
            <div class="card">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
                    <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
                </div>
                <div class="card-body">
                    <div class="row">
